final class WarehouseMock: Warehouse {
    private(set) var removed: [(String, Int)] = []
    var hasInventoryResult = true
    func hasInventory(_ sku: String, _ qty: Int) -> Bool { hasInventoryResult }
    func remove(_ sku: String, _ qty: Int) { removed.append((sku, qty)) }
}

func testFillRemovesStock() {
    let mock = WarehouseMock()
    XCTAssertTrue(Order(sku: "Talisker", qty: 50).fill(using: mock))
    XCTAssertEqual(mock.removed.map(\.0), ["Talisker"])
}
